# wp-content/languages/loco/ (Loco Translate ih učitava prije sistemskih prevoda;
# natpisi kojih ovdje nema ostaju iz sistemskog prevoda).
# Oblik: (domen, kontekst, msgid, msgid_plural, prevod) – kod množine prevod je lista od 3 oblika.

